/* Les angles · Essil, 5e (21/11, demandé par le papa) : 3 leçons du programme de 5e, sur le modèle des « Triangles au compas »,
   avec la jument d'Essil en fil rouge (la barrière, l'horloge de l'écurie, le gâteau aux carottes, la croisée, les ciseaux,
   l'échelle du grenier, la porte en Z, les barres au sol).
   1 · Nommer, mesurer, angles adjacents ; 2 · Complémentaires, supplémentaires, opposés par le sommet ;
   3 · Deux parallèles et une sécante : alternes-internes, correspondants, et comment reconnaître des parallèles.
   film : [{ img, vid, t }] ComfyUI + Wan 2.2 ; video : [{ c, t, v }] le cours au tableau ; atelier : { type:'rayons'|'croix'|'para', defis } ;
   memo, cartes ; ex : { entrainement, vie, defi } = fonctions (i) → question. */
(function(){
const R = (a, b) => a + Math.floor(Math.random() * (b - a + 1)), P = a => a[Math.floor(Math.random() * a.length)];
const A = (h, d = 0, cl = '') => `<div class="ap ${cl}" style="--d:${d}s">${h}</div>`;
const G = (h, d = 0) => A(h, d, 'grand');
const T = h => `<div class="tit">${h}</div>`;
const c1 = h => `<b class="c1">${h}</b>`, c2 = h => `<b class="c2">${h}</b>`, c3 = h => `<b class="c3">${h}</b>`;
const svg = (w, h, inner, y0 = 0) => `<svg viewBox="0 ${y0} ${w} ${h - y0}" class="fig">${inner}</svg>`;
const tr = (d, col = '#1f3c88', del = 0, w = 4, fill = 'none') => `<path d="${d}" pathLength="1000" class="tr" style="--d:${del}s" stroke="${col}" stroke-width="${w}" fill="${fill}" stroke-linecap="round" stroke-linejoin="round"/>`;
const tx = (x, y, s, del = 0, col = '#1c2340', sz = 22) => `<text x="${x.toFixed ? x.toFixed(1) : x}" y="${y.toFixed ? y.toFixed(1) : y}" class="ap" style="--d:${del}s" fill="${col}" font-size="${sz}" font-weight="800" text-anchor="middle">${s}</text>`;
const pt = (x, y, del = 0, col = '#ffd23f') => `<circle cx="${x}" cy="${y}" r="6" class="ap" style="--d:${del}s" fill="${col}"/>`;
// en degrés « de maths » : 0 = vers la droite, 90 = vers le haut (l'écran a l'axe y vers le bas)
const pol = (ox, oy, r, a) => [ox + r * Math.cos(a * Math.PI / 180), oy - r * Math.sin(a * Math.PI / 180)];
const ray = (ox, oy, L, a, col, del, w = 4) => { const [x, y] = pol(ox, oy, L, a); return tr(`M${ox} ${oy} L${x.toFixed(1)} ${y.toFixed(1)}`, col, del, w); };
const droite = (ox, oy, L, a, col, del, w = 4) => { const [x0, y0] = pol(ox, oy, L, a + 180), [x1, y1] = pol(ox, oy, L, a); return tr(`M${x0.toFixed(1)} ${y0.toFixed(1)} L${x1.toFixed(1)} ${y1.toFixed(1)}`, col, del, w); };
// un secteur d'angle coloré, de a0 à a1 (sens inverse des aiguilles), avec sa mesure ou son nom au milieu
const secteur = (ox, oy, r, a0, a1, col, del, lab = '', lcol = col, sz = 18) => { const [x0, y0] = pol(ox, oy, r, a0), [x1, y1] = pol(ox, oy, r, a1), [lx, ly] = pol(ox, oy, r + 22, (a0 + a1) / 2);
  return `<path d="M${ox} ${oy} L${x0.toFixed(1)} ${y0.toFixed(1)} A${r} ${r} 0 ${a1 - a0 > 180 ? 1 : 0} 0 ${x1.toFixed(1)} ${y1.toFixed(1)} Z" class="ap" style="--d:${del}s" fill="${col}" fill-opacity=".35" stroke="${col}" stroke-width="2"/>` + (lab ? tx(lx, ly + 6, lab, del, lcol, sz) : ''); };
const lab = (ox, oy, r, a, s, del, col = '#f4f1e6', sz = 20) => { const [x, y] = pol(ox, oy, r, a); return tx(x, y + 7, s, del, col, sz); };
const carre = (ox, oy, a, del, col = '#7fd6ff') => { const [x1, y1] = pol(ox, oy, 16, a), [x2, y2] = pol(ox, oy, 22.6, a + 45), [x3, y3] = pol(ox, oy, 16, a + 90);
  return `<path d="M${x1.toFixed(1)} ${y1.toFixed(1)} L${x2.toFixed(1)} ${y2.toFixed(1)} L${x3.toFixed(1)} ${y3.toFixed(1)}" fill="none" stroke="${col}" stroke-width="3" class="ap" style="--d:${del}s"/>`; };
const H = 'Ô';   // xÔy : le chapeau sur le sommet
const ch = (a, s, b) => a + s + '̂' + b;   // AB̂C

/* ---------- les figures des exercices (fond blanc) ---------- */
const N = '#1c2340';
// des demi-droites de même origine : rs = [[angle, nom]], marques = [[a0, a1, couleur, étiquette]]
const figRayons = (rs, marques = [], sommet = 'O', w = 360, h = 190, ox = 180, oy = 160) => svg(w, h, marques.map(([a0, a1, col, l]) => secteur(ox, oy, 40, a0, a1, col, 0, l, col, 16)).join('') + rs.map(([a, n]) => ray(ox, oy, 150, a, N, 0, 3) + lab(ox, oy, 165, a, n, 0, N, 18)).join('') + `<circle cx="${ox}" cy="${oy}" r="5" fill="${N}"/>` + tx(ox, oy + 24, sommet, 0, N, 18));
// deux droites qui se coupent en O, la 2e à l'angle t ; numéros 1 à 4 dans les 4 angles
const figCroix = (t, marques = {}) => { const ox = 180, oy = 100; let h = '';
  const sec = [[0, t], [t, 180], [180, 180 + t], [180 + t, 360]];
  sec.forEach(([a0, a1], i) => { const m = marques[i + 1]; if(m) h += secteur(ox, oy, 34, a0, a1, m[0], 0); h += lab(ox, oy, 52, (a0 + a1) / 2, m && m[1] != null ? m[1] : String(i + 1), 0, m ? m[0] : '#6b7590', 16); });
  return svg(360, 200, h + droite(ox, oy, 170, 0, N, 0, 3) + droite(ox, oy, 120, t, N, 0, 3) + `<circle cx="${ox}" cy="${oy}" r="4" fill="${N}"/>`); };
// deux droites (d1) en haut et (d2) en bas, une sécante ; les 8 angles numérotés : 1-4 en I1 (haut), 5-8 en I2 (bas),
// dans l'ordre : en haut à droite, en haut à gauche, en bas à gauche, en bas à droite. tau = inclinaison de (d2) (0 = parallèles).
const figPara = (s = 60, marques = {}, tau = 0, noms = true) => { const y1 = 60, I2 = [190, 160], k = (I2[1] - y1) / Math.sin(s * Math.PI / 180), I1 = [I2[0] + k * Math.cos(s * Math.PI / 180), y1];
  let h = droite(I1[0], y1, 220, 0, N, 0, 3) + droite(I2[0], I2[1], 220, tau, N, 0, 3) + droite(I2[0], I2[1], 175, s, '#7a4fe0', 0, 3);
  if(noms) h += tx(378, y1 - 8, '(d₁)', 0, N, 15) + tx(378, I2[1] - 8 - 188 * Math.tan(tau * Math.PI / 180), '(d₂)', 0, N, 15);
  const quad = (O, d, base) => [[d, s], [s, d + 180], [d + 180, s + 180], [s + 180, d + 360]].forEach(([a0, a1], i) => { const n = base + i, m = marques[n];
    if(m) h += secteur(O[0], O[1], 26, a0, a1, m[0], 0); if(m || noms) h += lab(O[0], O[1], 40, (a0 + a1) / 2, m && m[1] != null ? m[1] : String(n), 0, m ? m[0] : '#6b7590', 15); });
  quad(I1, 0, 1); quad(I2, tau, 5);
  return svg(400, 210, h); };

/* ---------- les générateurs communs ---------- */
const nature = a => a === 90 ? 'Droit' : a === 180 ? 'Plat' : a < 90 ? 'Aigu' : 'Obtus';
const qNature = a => ({ id:'nat-' + nature(a), q:`Un angle mesure <b>${a}°</b>. Quelle est sa nature ?`, opts:['Aigu', 'Droit', 'Obtus', 'Plat'], bon:nature(a), rep:nature(a).toLowerCase(),
  aide:'Aigu : moins de 90°. Droit : 90°. Obtus : entre 90° et 180°. Plat : 180°.', expl:`${a}° ${a < 90 ? 'est plus petit que 90° : aigu' : a === 90 ? ': un angle droit' : a === 180 ? ': un angle plat (un demi-tour)' : 'est entre 90° et 180° : obtus'}.` });
const PAIRES = { 'alternes-internes':[[3, 5], [4, 6]], 'correspondants':[[1, 5], [2, 6], [3, 7], [4, 8]], 'opposés par le sommet':[[1, 3], [2, 4], [5, 7], [6, 8]] };
const sorte = (i, j) => Object.keys(PAIRES).find(k => PAIRES[k].some(([a, b]) => (a === i && b === j) || (a === j && b === i)));
// la mesure de l'angle n quand (d1) // (d2) et que l'angle 1 mesure s
const mes = (n, s) => [1, 3, 5, 7].includes(n) ? s : 180 - s;

window.LECONS_ANG = [
/* ===================================================== 1 · nommer, mesurer, adjacents */
{ n:1, icon:'🐴', titre:'Les angles et les angles adjacents', sous:'Nommer, mesurer, reconnaître deux angles côte à côte',
  film:[
    { img:'angles/img/a1_0.webp', vid:'angles/img/a1_0.mp4', t:'Essil ouvre la grande barrière du paddock. Au coin, le poteau ne bouge pas ; la barrière tourne autour. Plus elle l\'ouvre, plus l\'écart entre la barrière et la clôture grandit : c\'est un angle ! Son sommet, c\'est le poteau ; ses côtés, la clôture et la barrière.' },
    { img:'angles/img/a1_1.webp', vid:'angles/img/a1_1.mp4', t:'Dans l\'écurie, Essil montre la grande horloge. Les deux aiguilles partent du même point, le centre : elles forment un angle. À trois heures, c\'est un angle droit, 90 degrés ; à six heures, un angle plat. Chaque heure, c\'est 30 degrés !' },
    { img:'angles/img/a1_2.webp', vid:'angles/img/a1_2.mp4', t:'C\'est l\'anniversaire de la jument : Essil coupe le gâteau aux carottes. Toutes les parts se touchent au centre. Deux parts voisines ont le même sommet, un bord commun, et elles ne se chevauchent pas : leurs angles sont adjacents.' } ],
  video:[
    { c:'Un angle', t:'Un angle, c\'est l\'ouverture entre deux demi-droites qui ont la même origine. L\'origine s\'appelle le sommet de l\'angle, et les deux demi-droites sont ses côtés. Comme la barrière et la clôture, accrochées au même poteau.',
      v:T('Un angle 🐴') + svg(420, 190, ray(120, 160, 260, 0, '#f2b632', .2, 5) + ray(120, 160, 230, 40, '#7fd6ff', .7, 5) + secteur(120, 160, 60, 0, 40, '#ff6b6b', 1.2) + pt(120, 160, .1) + tx(120, 186, 'sommet O', .3, '#ffd23f', 18) + lab(120, 160, 175, 52, 'côté [Oy)', 1, '#7fd6ff', 18) + tx(330, 185, 'côté [Ox)', .5, '#f2b632', 18)) },
    { c:'Le nommer', t:'Pour nommer un angle, on écrit trois lettres avec un petit chapeau sur celle du milieu, qui est toujours le sommet. Ici : l\'angle x O y. Avec des points, on dira l\'angle A B C, de sommet B. On peut le lire dans les deux sens : x O y, ou y O x.',
      v:T('Le nommer') + G(`x${c1('Ô')}y &nbsp;ou&nbsp; y${c1('Ô')}x`, .3) + A(`avec des points : ${ch('A', c1('B'), 'C')} → le sommet est ${c1('B')}`, 1) + A('la lettre du milieu = toujours le sommet', 1.7, 'etape') },
    { c:'Mesurer', t:'Pour mesurer un angle, on utilise le rapporteur. Son centre se place sur le sommet, et son zéro sur un côté. On lit la mesure, en degrés, là où passe l\'autre côté, en partant du zéro qu\'on a choisi.',
      v:T('Le rapporteur 📐') + svg(420, 190, `<path d="M70 160 A140 140 0 0 1 350 160 Z" class="ap" style="--d:.1s" fill="#ffd23f22" stroke="#ffd23f" stroke-width="2"/>` + [0, 30, 60, 90, 120, 150, 180].map((a, i) => lab(210, 160, 122, a, String(a), .2 + i * .05, '#ffd23f', 14)).join('') + ray(210, 160, 190, 0, '#f2b632', .7, 4) + ray(210, 160, 180, 55, '#7fd6ff', 1.1, 4) + secteur(210, 160, 50, 0, 55, '#ff6b6b', 1.5, '55°', '#ff9db0', 20) + pt(210, 160, .3)) },
    { c:'Les natures', t:'Selon sa mesure, un angle est aigu s\'il fait moins de 90 degrés, droit s\'il fait 90 degrés, obtus s\'il est entre 90 et 180 degrés, et plat s\'il fait 180 degrés : ses deux côtés forment alors une droite.',
      v:svg(460, 160, ray(40, 120, 90, 0, '#f4f1e6', .1, 3) + ray(40, 120, 90, 40, '#f4f1e6', .1, 3) + secteur(40, 120, 30, 0, 40, '#8fe3a8', .2) + tx(80, 150, 'aigu', .3, '#8fe3a8', 18)
        + ray(160, 120, 80, 0, '#f4f1e6', .5, 3) + ray(160, 120, 80, 90, '#f4f1e6', .5, 3) + carre(160, 120, 0, .6) + tx(195, 150, 'droit', .7, '#7fd6ff', 18)
        + ray(280, 120, 70, 0, '#f4f1e6', .9, 3) + ray(280, 120, 70, 130, '#f4f1e6', .9, 3) + secteur(280, 120, 26, 0, 130, '#f2b632', 1) + tx(290, 150, 'obtus', 1.1, '#f2b632', 18)
        + ray(400, 90, 50, 0, '#f4f1e6', 1.3, 3) + ray(400, 90, 50, 180, '#f4f1e6', 1.3, 3) + secteur(400, 90, 22, 0, 180, '#ff6b6b', 1.4) + tx(400, 130, 'plat', 1.5, '#ff9db0', 18)) + A('aigu &lt; 90° · droit = 90° · 90° &lt; obtus &lt; 180° · plat = 180°', 1.8) },
    { c:'L\'horloge', t:'Sur une horloge, un tour complet fait 360 degrés, partagés en 12 heures : chaque heure vaut 360 divisé par 12, soit 30 degrés. À 2 heures, les aiguilles font 60 degrés ; à 3 heures, 90 ; à 5 heures, 150.',
      v:T('L\'horloge de l\'écurie 🕒') + svg(420, 200, `<circle cx="210" cy="100" r="90" class="ap" style="--d:.1s" fill="#ffffff10" stroke="#f4f1e6" stroke-width="3"/>` + Array.from({ length:12 }, (_, i) => lab(210, 93, 76, 90 - i * 30, String(i || 12), .2, '#f4f1e6', 14)).join('') + ray(210, 100, 70, 90, '#ffd23f', .6, 5) + ray(210, 100, 55, 0, '#ff6b6b', 1, 6) + secteur(210, 100, 30, 0, 90, '#7fd6ff', 1.3) + pt(210, 100, .5)) + G('1 heure = 360 ÷ 12 = 30°', 1.7) },
    { c:'Angles adjacents', t:'Deux angles sont adjacents quand ils ont le même sommet, un côté commun, et qu\'ils sont situés de part et d\'autre de ce côté commun. Comme deux parts de gâteau voisines : même centre, un bord commun, et elles ne se chevauchent pas.',
      v:T('Adjacents = côte à côte') + svg(420, 180, ray(120, 160, 260, 0, '#f4f1e6', .1, 4) + ray(120, 160, 230, 35, '#ffd23f', .3, 6) + ray(120, 160, 150, 80, '#f4f1e6', .5, 4) + secteur(120, 160, 70, 0, 35, '#ff6b6b', .8, 'x' + H + 'y', '#ff9db0') + secteur(120, 160, 70, 35, 80, '#3d8bfd', 1.2, 'y' + H + 'z', '#7fd6ff') + pt(120, 160, .1) + lab(120, 160, 272, 0, 'x', .1) + lab(120, 160, 246, 35, 'y', .3, '#ffd23f') + lab(120, 160, 168, 80, 'z', .5)) + A(`① même sommet O · ② côté commun ${c3('[Oy)')} · ③ de part et d\'autre`, 1.6) },
    { c:'Pas adjacents !', t:'Attention aux pièges. Si les deux angles se chevauchent, du même côté du côté commun, ils ne sont pas adjacents. Et s\'ils n\'ont pas le même sommet, non plus, même s\'ils se touchent !',
      v:svg(460, 170, ray(60, 150, 170, 0, '#f4f1e6', .1, 3) + ray(60, 150, 160, 30, '#f4f1e6', .1, 3) + ray(60, 150, 150, 60, '#f4f1e6', .1, 3) + secteur(60, 150, 50, 0, 60, '#ff6b6b', .4) + secteur(60, 150, 75, 0, 30, '#3d8bfd', .7) + tx(130, 168, 'ils se chevauchent ✘', 1, '#ff9db0', 16)
        + ray(270, 150, 120, 0, '#f4f1e6', 1.2, 3) + ray(270, 150, 110, 55, '#f4f1e6', 1.2, 3) + ray(370, 60, 90, 0, '#f4f1e6', 1.4, 3) + ray(370, 60, 70, -70, '#f4f1e6', 1.4, 3) + secteur(270, 150, 36, 0, 55, '#ff6b6b', 1.6) + secteur(370, 60, 30, -70, 0, '#3d8bfd', 1.8) + tx(350, 168, '2 sommets ✘', 2, '#ff9db0', 16)) },
    { c:'Additionner', t:'Quand deux angles sont adjacents, le grand angle qu\'ils forment ensemble mesure la somme des deux. Si x O y mesure 35 degrés et y O z 45 degrés, alors x O z mesure 80 degrés. Et à l\'inverse, si x O z fait 80 degrés et x O y 35, y O z fait 80 moins 35 : 45 degrés.',
      v:T('Ils s\'additionnent') + svg(420, 170, ray(110, 150, 260, 0, '#f4f1e6', .1, 4) + ray(110, 150, 225, 35, '#ffd23f', .1, 4) + ray(110, 150, 145, 80, '#f4f1e6', .1, 4) + secteur(110, 150, 60, 0, 35, '#ff6b6b', .4, '35°', '#ff9db0') + secteur(110, 150, 60, 35, 80, '#3d8bfd', .8, '45°', '#7fd6ff') + secteur(110, 150, 120, 0, 80, '#f2b632', 1.3, '80°', '#ffd23f')) + G(`x${H}z = x${H}y + y${H}z`, 1.7) },
    { c:'À retenir', t:'À retenir. Un angle se nomme avec trois lettres, le sommet au milieu, sous le chapeau. Il se mesure en degrés au rapporteur. Aigu, droit, obtus ou plat. Deux angles adjacents ont le même sommet, un côté commun, et sont de part et d\'autre : leurs mesures s\'additionnent.',
      v:T('À retenir ⭐') + A(`x${c1('Ô')}y : le sommet au milieu`, .3, 'grand') + A('aigu &lt; 90° = droit &lt; obtus &lt; 180° = plat', 1) + A('adjacents : même sommet + côté commun + de part et d\'autre', 1.6) + A('adjacents → les mesures s\'additionnent', 2.2) } ],
  atelier:{ type:'rayons', nom:'📐 L\'atelier des angles', intro:'Fais tourner les demi-droites [Oy) et [Oz) avec le doigt (attrape le point au bout). Les angles se mesurent tout seuls, comme avec un rapporteur. Réussis chaque défi !',
    defis:[ { t:'Fais un angle aigu x' + H + 'y de 40°.', z:false, init:{ a:120 }, ok:s => s.a === 40 },
      { t:'Fais un angle obtus x' + H + 'y de 130°.', z:false, init:{ a:60 }, ok:s => s.a === 130 },
      { t:'Fais un angle droit : x' + H + 'y = 90°.', z:false, init:{ a:150 }, ok:s => s.a === 90 },
      { t:'Angles adjacents : fais x' + H + 'y = 50° et y' + H + 'z = 70°. Combien mesure alors x' + H + 'z ?', z:true, init:{ a:30, b:150 }, ok:s => s.a === 50 && s.b === 120 } ] },
  memo:[['Un angle', '<p>Deux demi-droites de même origine : l\'origine est le <b>sommet</b>, les demi-droites sont les <b>côtés</b>.</p>'],
    ['Le nommer', '<p>Trois lettres, le <b>sommet au milieu</b> sous le chapeau : x<b>Ô</b>y, ou ' + ch('A', '<b>B</b>', 'C') + ' (sommet B).</p>'],
    ['Mesurer', '<p>Au rapporteur, en <b>degrés</b> : centre sur le sommet, zéro sur un côté, on lit sur l\'autre côté.</p>'],
    ['Les natures', '<p><b>Aigu</b> &lt; 90° · <b>droit</b> = 90° · <b>obtus</b> entre 90° et 180° · <b>plat</b> = 180°. Sur une horloge, 1 heure = <b>30°</b>.</p>'],
    ['Angles adjacents', '<p>Même <b>sommet</b>, un <b>côté commun</b>, et situés <b>de part et d\'autre</b> de ce côté. Alors x' + H + 'z = x' + H + 'y + y' + H + 'z.</p>']],
  cartes:[['Comment s\'appelle le point d\'où partent les deux côtés ?', 'Le sommet.'], ['Dans ' + ch('A', 'B', 'C') + ', quel est le sommet ?', 'B, la lettre du milieu.'], ['Un angle de 90° est…', 'Droit.'], ['Un angle de 120° est…', 'Obtus.'], ['Un angle de 180° est…', 'Plat.'], ['Une heure sur l\'horloge, c\'est…', '30°.'], ['Adjacents : les 3 conditions ?', 'Même sommet, un côté commun, de part et d\'autre.'], ['x' + H + 'y = 35°, y' + H + 'z = 45° (adjacents) : x' + H + 'z ?', '80°.']],
  ex:{
    entrainement:i => { const k = i % 6;
      if(k === 0) return qNature(P([R(10, 85), R(95, 175), 90, 180]));
      if(k === 1){ const a = R(25, 70); return { id:'nom', q:'Comment s\'appelle cet angle ?', fig:figRayons([[0, 'x'], [a, 'y']], [[0, a, '#d7263d', '']]), opts:['x' + H + 'y', 'Ôxy', 'xŷO'], bon:'x' + H + 'y', rep:'x' + H + 'y', aide:'Le sommet se met au milieu.', expl:'Le sommet O est au milieu : x' + H + 'y (ou y' + H + 'x).' }; }
      if(k === 2){ const t = P([['A', 'B', 'C'], ['R', 'U', 'E'], ['M', 'N', 'P'], ['K', 'L', 'J']]); return { id:'sommet', q:`Quel est le sommet de l'angle <b>${ch(...t)}</b> ?`, opts:t.slice(), bon:t[1], rep:t[1], aide:'C\'est la lettre sous le chapeau.', expl:`La lettre du milieu, ${t[1]}, est le sommet.` }; }
      if(k === 3){ const c = P(['oui', 'chevauche', 'sommet']), a = R(30, 50), b = a + R(30, 50);
        const fig = c === 'oui' ? figRayons([[0, 'x'], [a, 'y'], [b, 'z']], [[0, a, '#d7263d', ''], [a, b, '#1f6fd8', '']]) : c === 'chevauche' ? figRayons([[0, 'x'], [a, 'y'], [b, 'z']], [[0, b, '#d7263d', ''], [0, a, '#1f6fd8', '']])
          : svg(360, 190, ray(60, 160, 140, 0, N, 0, 3) + ray(60, 160, 140, 45, N, 0, 3) + secteur(60, 160, 40, 0, 45, '#d7263d', 0) + ray(200, 160, 140, 0, N, 0, 3) + ray(200, 160, 130, 60, N, 0, 3) + secteur(200, 160, 40, 0, 60, '#1f6fd8', 0) + tx(60, 184, 'O', 0, N, 18) + tx(200, 184, 'P', 0, N, 18));
        return { id:'adj-' + c, q:'L\'angle <b style="color:#d7263d">rouge</b> et l\'angle <b style="color:#1f6fd8">bleu</b> sont-ils adjacents ?', fig, opts:['Oui', 'Non'], bon:c === 'oui' ? 'Oui' : 'Non', rep:c === 'oui' ? 'oui' : 'non',
          aide:'Vérifie les trois conditions : même sommet, côté commun, de part et d\'autre.', expl:c === 'oui' ? 'Même sommet O, côté commun [Oy), et de part et d\'autre : ils sont adjacents.' : c === 'chevauche' ? 'Ils ont le même sommet et un côté commun [Ox), mais ils se chevauchent (du même côté) : pas adjacents.' : 'Ils n\'ont pas le même sommet (O et P) : pas adjacents.' }; }
      if(k === 4){ const a = R(20, 70), b = R(20, 80); return { id:'somme', q:`x${H}y et y${H}z sont adjacents. x${H}y = <b>${a}°</b> et y${H}z = <b>${b}°</b>. Combien mesure x${H}z ?`, bon:a + b, rep:(a + b) + '°', unite:'°', aide:'Ils s\'additionnent.', expl:`${a} + ${b} = ${a + b}°.` }; }
      const t = R(90, 160), a = R(25, t - 25); return { id:'diff', q:`x${H}y et y${H}z sont adjacents, x${H}z = <b>${t}°</b> et x${H}y = <b>${a}°</b>. Combien mesure y${H}z ?`, bon:t - a, rep:(t - a) + '°', unite:'°', aide:'Le grand angle moins le petit.', expl:`${t} − ${a} = ${t - a}°.` }; },
    vie:i => { const k = i % 6;
      if(k === 0){ const h = P([1, 2, 3, 4, 5]); return { id:'heure', q:`Il est <b>${h} heure${h > 1 ? 's' : ''}</b> pile à l'horloge de l'écurie. Quel angle forment les deux aiguilles ?`, bon:30 * h, rep:30 * h + '°', unite:'°', aide:'Une heure = 30°.', expl:`${h} × 30 = ${30 * h}°.` }; }
      if(k === 1){ const h = P([1, 2, 4, 5, 3, 6]); return { id:'heure-nat', q:`À <b>${h} heures</b>, l'angle entre les aiguilles est…`, opts:['Aigu', 'Droit', 'Obtus', 'Plat'], bon:nature(30 * h), rep:nature(30 * h).toLowerCase(), aide:'Calcule d\'abord : une heure = 30°.', expl:`${h} × 30 = ${30 * h}° : ${nature(30 * h).toLowerCase()}.` }; }
      if(k === 2){ const n = P([6, 8, 10, 12, 9, 5]); return { id:'gateau', q:`Essil coupe le gâteau rond de la jument en <b>${n} parts égales</b>, toutes du centre. Quel est l'angle de chaque part ?`, bon:360 / n, rep:360 / n + '°', unite:'°', aide:'Un tour complet = 360°.', expl:`360 ÷ ${n} = ${360 / n}°. Deux parts voisines sont adjacentes.` }; }
      if(k === 3){ const a = R(25, 45), b = R(30, 60); return { id:'barriere', q:`La barrière s'ouvre d'abord de <b>${a}°</b>, puis Essil la pousse encore de <b>${b}°</b>. De combien est-elle ouverte ?`, bon:a + b, rep:(a + b) + '°', unite:'°', aide:'Les deux angles sont adjacents.', expl:`${a} + ${b} = ${a + b}°.` }; }
      if(k === 4){ const a = R(30, 60), b = R(30, 60); return { id:'plat3', q:`Au bord d'une barre bien droite, trois angles adjacents se suivent et remplissent un angle plat : <b>${a}°</b>, <b>${b}°</b> et le 3e. Combien mesure le 3e ?`, bon:180 - a - b, rep:(180 - a - b) + '°', unite:'°', aide:'Un angle plat = 180°.', expl:`180 − ${a} − ${b} = ${180 - a - b}°.` }; }
      const p = P([[3, 'Un quart'], [6, 'Un demi']]); return { id:'quart', q:`La jument fait ${p[1].toLowerCase()}-tour sur place. De combien de degrés a-t-elle tourné ?`, bon:p[0] * 30, rep:p[0] * 30 + '°', unite:'°', aide:'Un tour = 360°.', expl:`${p[1]} de 360°, c'est ${p[0] * 30}°.` }; },
    defi:i => { const k = i % 6;
      if(k === 0){ const a = R(20, 50); return { id:'double', q:`x${H}y et y${H}z sont adjacents et x${H}z mesure le <b>double</b> de x${H}y. Si x${H}y = <b>${a}°</b>, combien mesure y${H}z ?`, bon:a, rep:a + '°', unite:'°', aide:`x${H}z = 2 × ${a}.`, expl:`x${H}z = ${2 * a}°, donc y${H}z = ${2 * a} − ${a} = ${a}° : [Oy) partage l'angle en deux moitiés (c'est la bissectrice).` }; }
      if(k === 1){ const t = 2 * R(30, 80); return { id:'bissec', q:`[Oy) est la <b>bissectrice</b> de x${H}z, qui mesure <b>${t}°</b> : elle le coupe en deux angles adjacents égaux. Combien mesure x${H}y ?`, bon:t / 2, rep:t / 2 + '°', unite:'°', aide:'La moitié.', expl:`${t} ÷ 2 = ${t / 2}°.` }; }
      if(k === 2) return { id:'def', q:'Deux angles adjacents ont toujours…', opts:['Le même sommet et un côté commun', 'La même mesure', 'Une somme de 90°'], bon:'Le même sommet et un côté commun', rep:'le même sommet et un côté commun', aide:'Revois les trois conditions.', expl:'Même sommet, un côté commun, et ils sont de part et d\'autre de ce côté. Leurs mesures peuvent être quelconques.' };
      if(k === 3){ const h = P([[1, 30], [2, 30], [4, 30]]); const hh = h[0] + 0.5, a = Math.abs(30 * hh - 180); return { id:'demi', q:`À <b>${h[0]} h 30</b>, la grande aiguille est sur le 6, et la petite à mi-chemin entre le ${h[0]} et le ${h[0] + 1}. Quel angle forment-elles (le plus petit) ?`, bon:a, rep:a + '°', unite:'°', aide:'Compte les demi-heures : la petite aiguille est à ' + hh + ' heures.', expl:`Entre ${hh} heures et 6 heures, il y a ${6 - hh} heures : ${6 - hh} × 30 = ${a}°.` }; }
      if(k === 4){ const a = R(15, 35); return { id:'trois', q:`Trois angles adjacents de même mesure, x${H}y, y${H}z et z${H}t, forment ensemble un angle droit x${H}t. Combien mesure chacun ?`, bon:30, rep:'30°', unite:'°', aide:'90 ÷ 3.', expl:'90 ÷ 3 = 30°.' }; }
      const a = R(30, 70), b = R(20, 50); return { id:'reflexe', q:`x${H}y = ${a}° et y${H}z = ${b}° sont adjacents. Quel angle faut-il encore ajouter, adjacent à y${H}z de l'autre côté, pour arriver à un angle plat ?`, bon:180 - a - b, rep:(180 - a - b) + '°', unite:'°', aide:'Le plat = 180°.', expl:`180 − ${a} − ${b} = ${180 - a - b}°.` }; } } },

/* ===================================================== 2 · complémentaires, supplémentaires, opposés par le sommet */
{ n:2, icon:'✂️', titre:'Complémentaires, supplémentaires, opposés', sous:'Les couples d\'angles : 90°, 180°, et les angles opposés par le sommet',
  film:[
    { img:'angles/img/a2_0.webp', vid:'angles/img/a2_0.mp4', t:'Au paddock, Essil installe une croisée : deux barres qui se croisent en X. Autour du croisement, il y a quatre angles. Regarde bien : les deux angles du haut et du bas, face à face, ont exactement la même ouverture. Ils sont opposés par le sommet !' },
    { img:'angles/img/a2_1.webp', vid:'angles/img/a2_1.mp4', t:'Dans la sellerie, Essil ouvre ses grands ciseaux de toilettage. Les deux lames tournent autour de la vis, comme deux droites qui se coupent. Plus elle ouvre d\'un côté, plus ça s\'ouvre de l\'autre côté, exactement pareil.' },
    { img:'angles/img/a2_2.webp', vid:'angles/img/a2_2.mp4', t:'Pour monter au grenier à foin, Essil pose l\'échelle contre le mur de la grange. Le mur est droit, le sol est plat : ils font un angle droit. L\'angle de l\'échelle avec le sol et celui avec le mur se partagent les 90 degrés : ils sont complémentaires.' } ],
  video:[
    { c:'Complémentaires', t:'Deux angles sont complémentaires quand la somme de leurs mesures est égale à 90 degrés. Par exemple, 35 degrés et 55 degrés. Le complément d\'un angle de 35 degrés, c\'est 90 moins 35 : 55 degrés.',
      v:T('Complémentaires : 90°') + svg(420, 180, ray(130, 160, 240, 0, '#f4f1e6', .1, 4) + ray(130, 160, 150, 90, '#f4f1e6', .1, 4) + ray(130, 160, 220, 35, '#ffd23f', .4, 5) + carre(130, 160, 0, .2) + secteur(130, 160, 70, 0, 35, '#ff6b6b', .8, '35°', '#ff9db0') + secteur(130, 160, 70, 35, 90, '#3d8bfd', 1.2, '55°', '#7fd6ff')) + G('35° + 55° = 90°', 1.6) },
    { c:'Supplémentaires', t:'Deux angles sont supplémentaires quand la somme de leurs mesures est égale à 180 degrés. Par exemple, 120 et 60 degrés. Le supplément d\'un angle de 120 degrés, c\'est 180 moins 120 : 60 degrés.',
      v:T('Supplémentaires : 180°') + svg(420, 170, droite(210, 150, 190, 0, '#f4f1e6', .1, 4) + ray(210, 150, 150, 60, '#ffd23f', .4, 5) + secteur(210, 150, 60, 0, 60, '#3d8bfd', .8, '60°', '#7fd6ff') + secteur(210, 150, 60, 60, 180, '#ff6b6b', 1.2, '120°', '#ff9db0')) + G('120° + 60° = 180°', 1.6) },
    { c:'Le moyen de retenir', t:'Un petit truc pour ne pas les mélanger : C comme coin, le coin d\'un carré, 90 degrés, pour complémentaires. S comme surface toute plate, ou comme droite, 180 degrés, pour supplémentaires. Et dans l\'ordre de l\'alphabet : C avant S, 90 avant 180.',
      v:T('Le truc 💡') + G(`${c2('C')}omplémentaires → ${c2('90°')} (un coin)`, .3) + G(`${c1('S')}upplémentaires → ${c1('180°')} (tout plat)`, 1) + A('C avant S · 90 avant 180', 1.7, 'etape') },
    { c:'Pas forcément voisins', t:'Attention : deux angles complémentaires ou supplémentaires ne sont pas forcément adjacents. Un angle de 30 degrés ici et un angle de 60 degrés là-bas sont complémentaires, même s\'ils sont loin l\'un de l\'autre. Seule la somme compte.',
      v:svg(440, 150, ray(60, 120, 120, 0, '#f4f1e6', .1, 3) + ray(60, 120, 110, 30, '#f4f1e6', .1, 3) + secteur(60, 120, 50, 0, 30, '#ff6b6b', .3, '30°', '#ff9db0') + ray(280, 130, 120, 10, '#f4f1e6', .6, 3) + ray(280, 130, 110, 70, '#f4f1e6', .6, 3) + secteur(280, 130, 50, 10, 70, '#3d8bfd', .8, '60°', '#7fd6ff')) + G('30° + 60° = 90° → complémentaires', 1.2) + A('même s\'ils ne se touchent pas !', 1.8) },
    { c:'Opposés par le sommet', t:'Quand deux droites se coupent, elles forment quatre angles. Deux angles qui se font face, de part et d\'autre du point de croisement, sont opposés par le sommet : ils ont le même sommet, et leurs côtés sont dans le prolongement l\'un de l\'autre.',
      v:T('La croisée ✖️') + svg(420, 190, droite(210, 95, 190, 0, '#f4f1e6', .1, 4) + droite(210, 95, 130, 50, '#f4f1e6', .3, 4) + secteur(210, 95, 50, 0, 50, '#ff6b6b', .7, '1', '#ff9db0') + secteur(210, 95, 50, 180, 230, '#ff6b6b', 1.1, '3', '#ff9db0') + secteur(210, 95, 40, 50, 180, '#3d8bfd', 1.5, '2', '#7fd6ff') + secteur(210, 95, 40, 230, 360, '#3d8bfd', 1.9, '4', '#7fd6ff') + pt(210, 95, .2)) + A('1 et 3 sont opposés par le sommet · 2 et 4 aussi', 2.3) },
    { c:'La propriété', t:'La propriété très importante : deux angles opposés par le sommet ont la même mesure. Pourquoi ? L\'angle 1 et l\'angle 2 font ensemble un angle plat, 180 degrés. L\'angle 3 et l\'angle 2 aussi. Donc l\'angle 1 et l\'angle 3, c\'est 180 moins le même angle 2 : ils sont égaux !',
      v:T('Opposés par le sommet = égaux') + svg(420, 150, droite(210, 80, 190, 0, '#f4f1e6', .1, 3) + droite(210, 80, 110, 40, '#f4f1e6', .1, 3) + secteur(210, 80, 44, 0, 40, '#ff6b6b', .3, '1', '#ff9db0') + secteur(210, 80, 36, 40, 180, '#3d8bfd', .5, '2', '#7fd6ff') + secteur(210, 80, 44, 180, 220, '#ff6b6b', .7, '3', '#ff9db0')) + A(`1 + 2 = 180° et 3 + 2 = 180°`, 1) + G(`donc ${c3('1 = 3')}`, 1.7) },
    { c:'Les quatre angles', t:'Avec une seule mesure, on trouve les quatre angles de la croisée ! Si l\'angle 1 mesure 70 degrés : l\'angle 3, opposé, mesure aussi 70. L\'angle 2, adjacent et supplémentaire, mesure 180 moins 70 : 110 degrés. Et l\'angle 4, opposé à l\'angle 2, 110 aussi.',
      v:svg(420, 170, droite(210, 85, 190, 0, '#f4f1e6', .1, 3) + droite(210, 85, 110, 70, '#f4f1e6', .1, 3) + secteur(210, 85, 44, 0, 70, '#ff6b6b', .3, '70°', '#ff9db0') + secteur(210, 85, 44, 180, 250, '#ff6b6b', .9, '70°', '#ff9db0') + secteur(210, 85, 36, 70, 180, '#3d8bfd', 1.5, '110°', '#7fd6ff') + secteur(210, 85, 36, 250, 360, '#3d8bfd', 2.1, '110°', '#7fd6ff')) + A('opposé → 70° · adjacent → 180 − 70 = 110°', 2.5) },
    { c:'L\'échelle', t:'L\'échelle contre le mur : l\'angle avec le sol mesure 65 degrés. Le mur et le sol font un angle droit. Donc l\'angle entre l\'échelle et le mur mesure 90 moins 65 : 25 degrés. Les deux angles sont complémentaires.',
      v:T('L\'échelle du grenier 🪜') + svg(420, 190, tr('M60 170 H380', '#c9a26b', .1, 6) + tr('M300 170 V20', '#c9a26b', .1, 8) + carre(300, 170, 90, .3) + tr('M220 170 L300 18', '#ffd23f', .5, 7) + secteur(220, 170, 50, 0, 62, '#ff6b6b', .9, '65°', '#ff9db0') + secteur(300, 18, 50, 242, 270, '#3d8bfd', 1.3, '?', '#7fd6ff')) + G('90 − 65 = 25°', 1.7) },
    { c:'À retenir', t:'À retenir. Complémentaires : la somme fait 90 degrés. Supplémentaires : la somme fait 180 degrés. Deux angles opposés par le sommet ont la même mesure. Et deux angles adjacents qui forment un angle plat sont supplémentaires.',
      v:T('À retenir ⭐') + A(`complémentaires : somme = ${c2('90°')}`, .3, 'grand') + A(`supplémentaires : somme = ${c1('180°')}`, 1, 'grand') + A(`opposés par le sommet → ${c3('même mesure')}`, 1.7, 'grand') } ],
  atelier:{ type:'croix', nom:'✖️ L\'atelier de la croisée', intro:'Voici une croisée : deux droites qui se coupent en O. Fais tourner la barre penchée avec le doigt (attrape le point au bout). Les quatre angles se mesurent tout seuls : observe les angles opposés !',
    defis:[ { t:'Règle l\'angle 1 à 40°. Que vaut l\'angle 3, son opposé par le sommet ?', init:{ t:120 }, ok:s => s.t === 40 },
      { t:'Règle l\'angle 2 à 115°. Combien mesure l\'angle 1, qui lui est supplémentaire ?', init:{ t:30 }, ok:s => s.t === 65 },
      { t:'Rends les quatre angles égaux. Que vaut chacun ?', init:{ t:140 }, ok:s => s.t === 90 },
      { t:'Fais que l\'angle 2 soit le double de l\'angle 1 (ensemble ils font 180°).', init:{ t:100 }, ok:s => s.t === 60 } ] },
  memo:[['Complémentaires', '<p>Deux angles dont la <b>somme vaut 90°</b>. Le complément de a : <b>90 − a</b>.</p>'],
    ['Supplémentaires', '<p>Deux angles dont la <b>somme vaut 180°</b>. Le supplément de a : <b>180 − a</b>. Deux angles adjacents qui forment un angle plat sont supplémentaires.</p>'],
    ['Le truc', '<p><b>C</b> comme coin (90°) avant <b>S</b> comme surface plate (180°). Ils ne sont pas forcément adjacents : seule la somme compte.</p>'],
    ['Opposés par le sommet', '<p>Deux droites sécantes forment 4 angles. Deux angles <b>face à face</b> sont opposés par le sommet : ils ont <b>la même mesure</b>.</p>'],
    ['Les 4 angles d\'une croisée', '<p>Si un angle mesure a : son opposé mesure <b>a</b>, ses deux voisins mesurent <b>180 − a</b>. Les quatre ensemble font 360°.</p>']],
  cartes:[['Complémentaires : la somme fait…', '90°'], ['Supplémentaires : la somme fait…', '180°'], ['Le complément de 35° ?', '55°'], ['Le supplément de 120° ?', '60°'], ['Deux angles opposés par le sommet ont…', 'La même mesure.'], ['Croisée : un angle de 70°. Les trois autres ?', '110°, 70° et 110°.'], ['Complémentaires = forcément adjacents ?', 'Non, seule la somme compte.'], ['Échelle : 65° avec le sol. Avec le mur ?', '25° (complémentaires).']],
  ex:{
    entrainement:i => { const k = i % 6;
      if(k === 0){ const a = R(10, 80); return { id:'compl', q:`Quel est le complément d'un angle de <b>${a}°</b> ?`, bon:90 - a, rep:(90 - a) + '°', unite:'°', aide:'Complémentaires : la somme fait 90°.', expl:`90 − ${a} = ${90 - a}°.` }; }
      if(k === 1){ const a = R(20, 160); return { id:'suppl', q:`Quel est le supplément d'un angle de <b>${a}°</b> ?`, bon:180 - a, rep:(180 - a) + '°', unite:'°', aide:'Supplémentaires : la somme fait 180°.', expl:`180 − ${a} = ${180 - a}°.` }; }
      if(k === 2){ const t = P([[R(20, 70), 'c'], [R(30, 150), 's'], [R(20, 60), 'n']]); let a = t[0], b = t[1] === 'c' ? 90 - a : t[1] === 's' ? 180 - a : R(20, 70); if(t[1] === 'n' && (a + b === 90 || a + b === 180)) b++;
        const bon = a + b === 90 ? 'Complémentaires' : a + b === 180 ? 'Supplémentaires' : 'Ni l\'un ni l\'autre';
        return { id:'cs-' + bon, q:`Deux angles mesurent <b>${a}°</b> et <b>${b}°</b>. Ils sont…`, opts:['Complémentaires', 'Supplémentaires', 'Ni l\'un ni l\'autre'], bon, rep:bon.toLowerCase(), aide:'Additionne-les : 90° ? 180° ?', expl:`${a} + ${b} = ${a + b}° : ${bon.toLowerCase()}.` }; }
      if(k === 3){ const t = R(35, 75), n = P([1, 2]); const v = n === 1 ? t : 180 - t;
        return { id:'oppo', q:`Sur la croisée, l'angle ${n} mesure <b>${v}°</b>. Combien mesure l'angle ${n + 2} ?`, fig:figCroix(t, { [n]:['#d7263d', v + '°'], [n + 2]:['#1f6fd8', '?'] }), bon:v, rep:v + '°', unite:'°', aide:'Ils sont face à face : opposés par le sommet.', expl:`Opposés par le sommet : même mesure, ${v}°.` }; }
      if(k === 4){ const t = R(35, 75); return { id:'voisin', q:`Sur la croisée, l'angle 1 mesure <b>${t}°</b>. Combien mesure l'angle 2 ?`, fig:figCroix(t, { 1:['#d7263d', t + '°'], 2:['#1f6fd8', '?'] }), bon:180 - t, rep:(180 - t) + '°', unite:'°', aide:'Ensemble, ils forment un angle plat.', expl:`Adjacents et supplémentaires : 180 − ${t} = ${180 - t}°.` }; }
      return { id:'propr', q:'Deux angles opposés par le sommet…', opts:['Ont la même mesure', 'Sont complémentaires', 'Sont supplémentaires'], bon:'Ont la même mesure', rep:'ont la même mesure', aide:'Revois la croisée.', expl:'Opposés par le sommet → même mesure. (Ce sont les voisins qui sont supplémentaires.)' }; },
    vie:i => { const k = i % 6;
      if(k === 0){ const a = R(55, 78); return { id:'echelle', q:`L'échelle du grenier fait un angle de <b>${a}°</b> avec le sol. Le mur est perpendiculaire au sol. Quel angle fait l'échelle avec le mur ?`, bon:90 - a, rep:(90 - a) + '°', unite:'°', aide:'Les deux angles se partagent l\'angle droit.', expl:`90 − ${a} = ${90 - a}° : ils sont complémentaires.` }; }
      if(k === 1){ const a = R(25, 60); return { id:'ciseaux', q:`Essil ouvre ses ciseaux : les lames font un angle de <b>${a}°</b> du côté de la lame. Quel angle font les anneaux, de l'autre côté de la vis ?`, bon:a, rep:a + '°', unite:'°', aide:'Les deux angles sont face à face.', expl:`Opposés par le sommet : ${a}°.` }; }
      if(k === 2){ const a = R(40, 80); return { id:'croisee', q:`Les barres de la croisée forment, en haut, un angle de <b>${2 * a}°</b>. Quel est l'angle sur le côté, à gauche ?`, bon:180 - 2 * a, rep:(180 - 2 * a) + '°', unite:'°', aide:'L\'angle du côté est voisin de celui du haut.', expl:`Voisins sur une barre droite : 180 − ${2 * a} = ${180 - 2 * a}°.` }; }
      if(k === 3){ const a = R(110, 150); return { id:'planche', q:`Sur la porte de l'écurie, une planche en biais fait un angle de <b>${a}°</b> avec la planche du bas (bien droite). Quel est l'autre angle, de l'autre côté ?`, bon:180 - a, rep:(180 - a) + '°', unite:'°', aide:'Ils forment un angle plat.', expl:`180 − ${a} = ${180 - a}°.` }; }
      if(k === 4){ const a = R(20, 40); return { id:'rampe', q:`La rampe du van monte avec un angle de <b>${a}°</b> par rapport au sol. Quel est son angle avec le panneau vertical du van ?`, bon:90 - a, rep:(90 - a) + '°', unite:'°', aide:'Le sol et le panneau vertical font 90°.', expl:`90 − ${a} = ${90 - a}°.` }; }
      const t = R(50, 80); return { id:'quatre', q:`Deux chemins droits se croisent dans la forêt. L'un des angles mesure <b>${t}°</b>. Combien vaut la somme des quatre angles ?`, bon:360, rep:'360°', unite:'°', aide:'Deux angles plats.', expl:`${t} + ${180 - t} + ${t} + ${180 - t} = 360° : un tour complet.` }; },
    defi:i => { const k = i % 6;
      if(k === 0) return { id:'triple', q:'Sur une croisée, l\'angle 2 mesure le <b>triple</b> de l\'angle 1. Combien mesure l\'angle 1 ?', bon:45, rep:'45°', unite:'°', aide:'Angle 1 + angle 2 = 180°, et angle 2 = 3 × angle 1.', expl:'4 fois l\'angle 1 = 180°, donc l\'angle 1 = 45° (et l\'angle 2 = 135°).' };
      if(k === 1) return { id:'egaux', q:'Deux angles sont <b>complémentaires</b> et ont la <b>même mesure</b>. Combien mesure chacun ?', bon:45, rep:'45°', unite:'°', aide:'90 ÷ 2.', expl:'90 ÷ 2 = 45°.' };
      if(k === 2){ const d = 2 * R(10, 30); return { id:'ecart', q:`Deux angles supplémentaires : l'un mesure <b>${d}° de plus</b> que l'autre. Combien mesure le plus petit ?`, bon:(180 - d) / 2, rep:(180 - d) / 2 + '°', unite:'°', aide:`Enlève d'abord ${d}° à 180°, puis partage en deux.`, expl:`(180 − ${d}) ÷ 2 = ${(180 - d) / 2}° (et l'autre ${(180 + d) / 2}°).` }; }
      if(k === 3){ const t = R(40, 80); return { id:'trois-sur-quatre', q:`Sur une croisée, la somme de trois des quatre angles fait <b>${180 + t}°</b>. Combien mesure le 4e ?`, bon:180 - t, rep:(180 - t) + '°', unite:'°', aide:'Les quatre angles font 360°.', expl:`360 − ${180 + t} = ${180 - t}°.` }; }
      if(k === 4) return { id:'vrai-faux', q:'« Deux angles complémentaires sont toujours adjacents. » Vrai ou faux ?', opts:['Faux', 'Vrai'], bon:'Faux', rep:'faux', aide:'Que faut-il pour être complémentaires ?', expl:'Faux : il suffit que leur somme fasse 90°, ils peuvent être n\'importe où.' };
      const a = R(20, 40); return { id:'compl-suppl', q:`Le complément d'un angle mesure <b>${a}°</b>. Combien mesure le supplément de ce même angle ?`, bon:90 + a, rep:(90 + a) + '°', unite:'°', aide:'Trouve d\'abord l\'angle : 90 − ' + a + '.', expl:`L'angle mesure 90 − ${a} = ${90 - a}°, son supplément 180 − ${90 - a} = ${90 + a}°.` }; } } },

/* ===================================================== 3 · parallèles et sécante */
{ n:3, icon:'🚪', titre:'Parallèles et sécante', sous:'Angles alternes-internes, correspondants, et reconnaître des parallèles',
  film:[
    { img:'angles/img/a3_0.webp', vid:'angles/img/a3_0.mp4', t:'Essil repeint la porte de l\'écurie. En haut et en bas, deux planches horizontales, bien parallèles. Entre elles, des planches en biais. Suis une seule planche en biais avec le haut et le bas : elle dessine un grand Z ! Les deux angles dans les coins du Z, à l\'intérieur, de part et d\'autre de la planche en biais, sont exactement pareils.' },
    { img:'angles/img/a3_1.webp', vid:'angles/img/a3_1.mp4', t:'Au manège, les barres au sol sont toutes parallèles. Essil les traverse en diagonale avec sa jument, en ligne droite. À chaque barre, le chemin de la jument fait le même angle avec la barre : ce sont des angles correspondants.' },
    { img:'angles/img/a3_2.webp', vid:'angles/img/a3_2.mp4', t:'Le soir, Essil trace sur son cahier deux droites parallèles et une sécante qui les coupe. Elle colorie en rouge deux angles égaux. Et elle découvre le secret : si ces angles sont égaux, alors les droites sont parallèles !' } ],
  video:[
    { c:'Une sécante', t:'Deux droites, d un et d deux, et une troisième droite qui les coupe toutes les deux : on l\'appelle une sécante. Elle forme quatre angles en haut, au point I, et quatre angles en bas, au point J. Huit angles en tout !',
      v:T('Deux droites + une sécante') + svg(420, 190, droite(250, 50, 190, 0, '#f4f1e6', .1, 4) + droite(170, 150, 190, 0, '#f4f1e6', .3, 4) + droite(170, 150, 170, 51, '#c9f', .6, 4) + pt(250, 50, 1) + pt(170, 150, 1) + tx(265, 38, 'I', 1.1, '#ffd23f', 18) + tx(152, 172, 'J', 1.1, '#ffd23f', 18) + tx(400, 42, '(d₁)', .2, '#f4f1e6', 16) + tx(400, 142, '(d₂)', .4, '#f4f1e6', 16)) + A('la sécante coupe les deux droites', 1.4) },
    { c:'Alternes-internes', t:'Deux angles sont alternes-internes quand ils sont entre les deux droites, à l\'intérieur, et de part et d\'autre de la sécante, en alternance, un de chaque côté. Ils dessinent un Z, ou un Z à l\'envers. Comme les coins de la porte de l\'écurie !',
      v:T('Alternes-internes = le Z') + svg(420, 190, droite(250, 50, 190, 0, '#f4f1e6', .1, 3) + droite(170, 150, 190, 0, '#f4f1e6', .1, 3) + droite(170, 150, 170, 51, '#c9f', .1, 3) + secteur(250, 50, 36, 180, 231, '#ff6b6b', .5) + secteur(170, 150, 36, 0, 51, '#ff6b6b', .9) + tr('M90 50 H250 L170 150 H330', '#ffd23f', 1.3, 6)) + A('entre les droites · de part et d\'autre de la sécante', 2) },
    { c:'Correspondants', t:'Deux angles sont correspondants quand ils sont du même côté de la sécante, l\'un au-dessus de d un, l\'autre au-dessus de d deux : ils sont à la même place, l\'un en haut, l\'autre en bas. Ils dessinent un F.',
      v:T('Correspondants = le F') + svg(420, 190, droite(250, 50, 190, 0, '#f4f1e6', .1, 3) + droite(170, 150, 190, 0, '#f4f1e6', .1, 3) + droite(170, 150, 170, 51, '#c9f', .1, 3) + secteur(250, 50, 36, 0, 51, '#3d8bfd', .5) + secteur(170, 150, 36, 0, 51, '#3d8bfd', .9) + tr('M290 1 L170 150 M250 50 H360 M170 150 H280', '#ffd23f', 1.3, 6)) + A('même côté de la sécante · même place', 2) },
    { c:'Si les droites sont parallèles', t:'La grande propriété : si deux droites parallèles sont coupées par une sécante, alors les angles alternes-internes ont la même mesure, et les angles correspondants ont la même mesure. C\'est le Z et le F qui gardent leurs angles !',
      v:T('Si (d₁) // (d₂)…') + svg(420, 190, droite(250, 50, 190, 0, '#f4f1e6', .1, 3) + droite(170, 150, 190, 0, '#f4f1e6', .1, 3) + droite(170, 150, 170, 51, '#c9f', .1, 3) + secteur(250, 50, 36, 180, 231, '#ff6b6b', .4, '51°', '#ff9db0') + secteur(170, 150, 36, 0, 51, '#ff6b6b', .7, '51°', '#ff9db0') + secteur(250, 50, 30, 0, 51, '#3d8bfd', 1, '51°', '#7fd6ff')) + A('…alors alternes-internes ' + c3('égaux') + ' et correspondants ' + c3('égaux'), 1.5) },
    { c:'Calculer', t:'Exemple : d un et d deux sont parallèles, et l\'angle 1 mesure 65 degrés. L\'angle 5, correspondant, mesure aussi 65. L\'angle 3 est opposé à l\'angle 1 : 65. Et l\'angle 4, voisin, mesure 180 moins 65 : 115 degrés. Avec un seul angle, on trouve les huit !',
      v:svg(420, 210, figPara(65, { 1:['#ff6b6b', '65°'], 5:['#3d8bfd', '65°'], 3:['#ff6b6b', '65°'], 4:['#f2b632', '115°'] }).replace(/<svg[^>]*>|<\/svg>/g, '').replace(/#1c2340/g, '#f4f1e6').replace(/#6b7590/g, '#9aa6c0')) + A('2 valeurs seulement : 65° et 180 − 65 = 115°', 1) },
    { c:'Reconnaître des parallèles', t:'Et à l\'envers ! Si deux droites coupées par une sécante forment des angles alternes-internes de même mesure, ou des angles correspondants de même mesure, alors ces deux droites sont parallèles. C\'est comme ça qu\'on prouve que deux droites sont parallèles, sans règle ni équerre.',
      v:T('Pour prouver des parallèles') + A('si alternes-internes ' + c3('égaux'), .3, 'grand') + A('ou correspondants ' + c3('égaux'), .9, 'grand') + G('alors (d₁) // (d₂) ✔', 1.6) },
    { c:'Pas parallèles', t:'Et si les angles ne sont pas égaux ? Par exemple, des angles correspondants de 70 et de 74 degrés. Alors les droites ne sont pas parallèles : elles finiront par se couper, quelque part, plus loin.',
      v:svg(420, 210, figPara(70, { 1:['#ff6b6b', '70°'], 5:['#3d8bfd', '74°'] }, -4, false).replace(/<svg[^>]*>|<\/svg>/g, '').replace(/#1c2340/g, '#f4f1e6').replace(/#6b7590/g, '#9aa6c0')) + G('70° ≠ 74° → pas parallèles ✘', .8) },
    { c:'Les barres au sol', t:'Au manège : les barres au sol sont parallèles, et le chemin de la jument coupe la première barre avec un angle de 70 degrés. À la barre suivante, l\'angle correspondant mesure aussi 70 degrés, et l\'angle alterne-interne aussi. La jument garde le même angle tout du long !',
      v:T('Les barres au sol 🐴') + svg(420, 190, tr('M40 50 H380', '#f2b632', .1, 8) + tr('M40 150 H380', '#f2b632', .2, 8) + droite(173, 150, 180, 70, '#c9f', .5, 4) + secteur(209.4, 50, 34, 0, 70, '#ff6b6b', .9, '70°', '#ff9db0') + secteur(173, 150, 34, 0, 70, '#ff6b6b', 1.3, '70°', '#ff9db0')) + A('correspondants : 70° = 70°', 1.7) },
    { c:'À retenir', t:'À retenir. Alternes-internes : entre les droites, de part et d\'autre de la sécante, le Z. Correspondants : du même côté de la sécante, à la même place, le F. Si les droites sont parallèles, ces angles sont égaux. Et si ces angles sont égaux, les droites sont parallèles.',
      v:T('À retenir ⭐') + A('alternes-internes : le ' + c1('Z') + ' · correspondants : le ' + c2('F'), .3, 'grand') + A('droites // → angles égaux', 1) + A('angles égaux → droites //', 1.6) } ],
  atelier:{ type:'para', nom:'🚪 L\'atelier des parallèles', intro:'Deux droites (d₁) et (d₂) et une sécante. Fais tourner la sécante (point violet) ou penche (d₂) (point bleu). Les angles <b style="color:#d7263d">1</b>, <b style="color:#2f9e44">3</b> et <b style="color:#1f6fd8">5</b> se mesurent tout seuls.',
    defis:[ { t:'Rends (d₁) et (d₂) parallèles en rendant les angles correspondants 1 et 5 égaux.', init:{ s:60, tau:14 }, ok:s => s.tau === 0 },
      { t:'Les droites sont parallèles : règle la sécante pour que l\'angle 1 mesure 70°. Combien mesure l\'angle alterne-interne 3 ? et 5 ?', init:{ s:110, tau:0 }, ok:s => s.tau === 0 && s.s === 70 },
      { t:'Fais des angles correspondants 1 et 5 de 50° et 60° : les droites sont-elles parallèles ?', init:{ s:80, tau:0 }, ok:s => s.s === 50 && s.s - s.tau === 60 },
      { t:'Rends les droites parallèles avec une sécante perpendiculaire : angle 1 = 90°.', init:{ s:45, tau:-10 }, ok:s => s.tau === 0 && s.s === 90 } ] },
  memo:[['La figure', '<p>Deux droites (d₁) et (d₂) coupées par une <b>sécante</b> : 4 angles en I, 4 angles en J.</p>' + figPara(60)],
    ['Alternes-internes', '<p><b>Entre</b> les deux droites et <b>de part et d\'autre</b> de la sécante : le <b>Z</b>. (3 et 5 ; 4 et 6)</p>'],
    ['Correspondants', '<p>Du <b>même côté</b> de la sécante, à la <b>même place</b> : le <b>F</b>. (1 et 5 ; 2 et 6 ; 3 et 7 ; 4 et 8)</p>'],
    ['Si les droites sont parallèles', '<p>Alors les angles alternes-internes sont <b>égaux</b>, et les angles correspondants sont <b>égaux</b>.</p>'],
    ['Pour prouver que des droites sont parallèles', '<p>Si deux angles alternes-internes (ou correspondants) sont <b>égaux</b>, alors les droites sont <b>parallèles</b>. S\'ils sont différents, elles ne le sont pas.</p>']],
  cartes:[['Le Z, ce sont les angles…', 'Alternes-internes.'], ['Le F, ce sont les angles…', 'Correspondants.'], ['Alternes-internes : où sont-ils ?', 'Entre les droites, de part et d\'autre de la sécante.'], ['(d₁) // (d₂), angle 1 = 65° : angle 5 (correspondant) ?', '65°'], ['(d₁) // (d₂), angle 1 = 65° : angle 4 ?', '115° (180 − 65).'], ['Correspondants de 72° et 72° : les droites ?', 'Parallèles.'], ['Correspondants de 70° et 74° : les droites ?', 'Pas parallèles.'], ['Combien d\'angles avec 2 droites et 1 sécante ?', '8 angles.']],
  ex:{
    entrainement:i => { const k = i % 6;
      if(k < 3){ const s = R(45, 70), pr = P([...PAIRES['alternes-internes'], ...PAIRES['correspondants'], ...PAIRES['opposés par le sommet']]), bon = sorte(...pr), lab = bon.charAt(0).toUpperCase() + bon.slice(1);
        return { id:'paire-' + bon, q:`Les angles <b style="color:#d7263d">${pr[0]}</b> et <b style="color:#1f6fd8">${pr[1]}</b> sont…`, fig:figPara(s, { [pr[0]]:['#d7263d', null], [pr[1]]:['#1f6fd8', null] }), opts:['Alternes-internes', 'Correspondants', 'Opposés par le sommet'], bon:lab, rep:bon,
          aide:'Le Z (entre les droites, de part et d\'autre) ? Le F (même place) ? Face à face (même sommet) ?', expl:bon === 'alternes-internes' ? 'Entre les droites et de part et d\'autre de la sécante : le Z.' : bon === 'correspondants' ? 'Même côté de la sécante, même place en haut et en bas : le F.' : 'Même sommet, face à face : opposés par le sommet.' }; }
      if(k === 3){ const s = R(40, 75), n = P([5, 7]); return { id:'corr', q:`(d₁) et (d₂) sont parallèles. L'angle 1 mesure <b>${s}°</b>. Combien mesure l'angle ${n} ?`, fig:figPara(s, { 1:['#d7263d', s + '°'], [n]:['#1f6fd8', '?'] }), bon:s, rep:s + '°', unite:'°', aide:n === 5 ? 'Les angles 1 et 5 sont correspondants.' : 'L\'angle 7 est opposé à 5, qui correspond à 1.', expl:n === 5 ? `Correspondants et droites parallèles : ${s}°.` : `5 = 1 (correspondants) et 7 = 5 (opposés) : ${s}°.` }; }
      if(k === 4){ const s = R(40, 75); return { id:'alt', q:`(d₁) et (d₂) sont parallèles. L'angle 3 mesure <b>${s}°</b>. Combien mesure l'angle 5 ?`, fig:figPara(s, { 3:['#d7263d', s + '°'], 5:['#1f6fd8', '?'] }), bon:s, rep:s + '°', unite:'°', aide:'3 et 5 font un Z.', expl:`Alternes-internes et droites parallèles : ${s}°.` }; }
      const s = R(40, 75), n = P([2, 4, 6, 8]); return { id:'suppl8', q:`(d₁) et (d₂) sont parallèles. L'angle 1 mesure <b>${s}°</b>. Combien mesure l'angle ${n} ?`, fig:figPara(s, { 1:['#d7263d', s + '°'], [n]:['#1f6fd8', '?'] }), bon:180 - s, rep:(180 - s) + '°', unite:'°', aide:'Cet angle est voisin d\'un angle égal à l\'angle 1 : supplémentaires.', expl:`180 − ${s} = ${180 - s}°.` }; },
    vie:i => { const k = i % 6;
      if(k === 0){ const a = R(35, 55); return { id:'porte', q:`Sur la porte de l'écurie, les deux planches horizontales sont parallèles. La planche en biais fait un angle de <b>${a}°</b> avec celle du haut, à l'intérieur du Z. Quel angle fait-elle avec celle du bas, dans l'autre coin du Z ?`, bon:a, rep:a + '°', unite:'°', aide:'Les deux coins du Z : alternes-internes.', expl:`Alternes-internes et planches parallèles : ${a}°.` }; }
      if(k === 1){ const a = R(55, 80); return { id:'barres', q:`Les barres au sol sont parallèles. Le chemin de la jument fait un angle de <b>${a}°</b> avec la 1re barre. Quel angle fait-il avec la 2e barre, à la même place ?`, bon:a, rep:a + '°', unite:'°', aide:'À la même place : correspondants.', expl:`Correspondants et barres parallèles : ${a}°.` }; }
      if(k === 2){ const a = R(55, 80), b = a + P([-3, -2, 2, 3]); return { id:'route', q:`Deux allées du club croisent la même route droite. Les angles correspondants mesurent <b>${a}°</b> et <b>${b}°</b>. Les allées sont-elles parallèles ?`, opts:['Non', 'Oui'], bon:'Non', rep:'non', aide:'Compare les deux angles.', expl:`${a}° ≠ ${b}° : elles ne sont pas parallèles (elles se rejoindront plus loin).` }; }
      if(k === 3){ const a = R(55, 80); return { id:'route-ok', q:`Deux clôtures sont coupées par un chemin droit. Les angles alternes-internes mesurent <b>${a}°</b> et <b>${a}°</b>. Les clôtures sont-elles parallèles ?`, opts:['Oui', 'Non'], bon:'Oui', rep:'oui', aide:'Alternes-internes égaux…', expl:'Alternes-internes égaux : les clôtures sont parallèles.' }; }
      if(k === 4){ const a = R(110, 140); return { id:'escalier', q:`Les marches de l'escalier du grenier sont parallèles. La rampe fait un angle de <b>${a}°</b> avec une marche. Quel angle fait-elle avec la marche suivante, à la même place ?`, bon:a, rep:a + '°', unite:'°', aide:'Même place : correspondants.', expl:`Correspondants : ${a}°.` }; }
      const a = R(50, 75); return { id:'z-suppl', q:`Porte de l'écurie : planches parallèles, la planche en biais fait <b>${a}°</b> avec celle du haut (dans un coin du Z). Quel angle fait-elle avec celle du bas, du même côté de la planche en biais, entre les planches ?`, bon:180 - a, rep:(180 - a) + '°', unite:'°', aide:'L\'angle du bas égal à ' + a + '° est de l\'autre côté ; celui-ci est son voisin.', expl:`Voisin de l'angle alterne-interne de ${a}° : 180 − ${a} = ${180 - a}°.` }; },
    defi:i => { const k = i % 6;
      if(k === 0){ const s = R(40, 70); return { id:'chaine6', q:`(d₁) // (d₂), l'angle 1 mesure <b>${s}°</b>. Combien mesure l'angle 6 ?`, fig:figPara(s, { 1:['#d7263d', s + '°'], 6:['#1f6fd8', '?'] }), bon:180 - s, rep:(180 - s) + '°', unite:'°', aide:'L\'angle 6 correspond à l\'angle 2, voisin de l\'angle 1.', expl:`2 = 180 − ${s} = ${180 - s}°, et 6 = 2 (correspondants).` }; }
      if(k === 1){ const s = R(40, 70), n = R(1, 8), m = R(1, 8); const v = mes(n, s), w = mes(m, s); return { id:'chaine', q:`(d₁) // (d₂), l'angle ${n} mesure <b>${v}°</b>. Combien mesure l'angle ${m === n ? (m % 8) + 1 : m} ?`, fig:figPara(s, { [n]:['#d7263d', v + '°'], [m === n ? (m % 8) + 1 : m]:['#1f6fd8', '?'] }), bon:mes(m === n ? (m % 8) + 1 : m, s), rep:mes(m === n ? (m % 8) + 1 : m, s) + '°', unite:'°', aide:'Il n\'y a que deux mesures sur la figure : a et 180 − a.', expl:`Les angles 1, 3, 5, 7 mesurent ${s}° ; les angles 2, 4, 6, 8 mesurent ${180 - s}°.` }; }
      if(k === 2) return { id:'reciproque', q:'Pour prouver que deux droites sont parallèles, il suffit de montrer que…', opts:['Deux angles alternes-internes sont égaux', 'Deux angles opposés par le sommet sont égaux', 'Deux angles voisins font 180°'], bon:'Deux angles alternes-internes sont égaux', rep:'deux angles alternes-internes sont égaux', aide:'Les angles opposés et voisins sont toujours comme ça, parallèles ou pas.', expl:'Alternes-internes (ou correspondants) égaux → parallèles. Les opposés par le sommet sont toujours égaux, ça ne prouve rien.' };
      if(k === 3){ const a = R(50, 70); return { id:'z2', q:`Une sécante coupe (d₁) et (d₂). Un angle en I mesure <b>${a}°</b> ; en J, l'angle alterne-interne mesure <b>${180 - a}°</b>. Les droites sont-elles parallèles ?`, opts:['Non', 'Oui'], bon:'Non', rep:'non', aide:'Pour être parallèles, il faudrait des alternes-internes égaux.', expl:`${a}° ≠ ${180 - a}° : pas parallèles.` }; }
      if(k === 4){ const a = R(30, 60); return { id:'trois-droites', q:`(d₁) // (d₂) et la sécante est perpendiculaire à (d₁). Quel angle fait-elle avec (d₂) ?`, bon:90, rep:'90°', unite:'°', aide:'Angle 1 = 90°, et les correspondants sont égaux.', expl:'90° : une droite perpendiculaire à l\'une de deux parallèles est perpendiculaire à l\'autre.' }; }
      const a = R(110, 140); return { id:'triangle-para', q:`Dans un triangle ABC, la droite (d) passe par A et est parallèle à (BC). L'angle entre (d) et [AB] mesure <b>${180 - a}°</b>, dans un Z avec l'angle en B. Combien mesure l'angle ${ch('A', 'B', 'C')} ?`, bon:180 - a, rep:(180 - a) + '°', unite:'°', aide:'Le Z : alternes-internes, donc égaux.', expl:`Alternes-internes avec (d) // (BC) : ${ch('A', 'B', 'C')} = ${180 - a}°. C'est l'idée de la preuve des 180° du triangle !` }; } } }
];
})();
